archiveSession(id: string, archivedAt = Date.now()): StudioSession {
  const tx = this.db.transaction(() => {
    const existing = this.getSessionRow(id);
    if (!existing) throw new Error(`session not found: ${id}`);
    if (existing.archived_at != null) {
